public function register(Panel $panel): void
{
    $panel
        ->plugin(MinimalTheme::make())
        ->viteTheme('vendor/atrioteam/digital-hub/resources/theme/digital-hub-theme.css')
        ->font('Open Sans')
        ->pages([
            Catalog::class,
            AssetManager::class,
            ManageGeneralSettings::class,
        ])
        // Voce "Impostazioni" nello user menu (dropdown del badge utente),
        // non in sidebar (la pagina ha shouldRegisterNavigation = false).
        // Visibile solo a chi può gestire le impostazioni.
        ->userMenuItems([
            Action::make('settings')
                ->label('Impostazioni')
                ->icon(Heroicon::OutlinedCog6Tooth)
                ->url(fn (): string => ManageGeneralSettings::getUrl())
                ->visible(fn (): bool => ManageGeneralSettings::canAccess()),
        ])
        // Immagine di sfondo nella schermata di login. Il path è gestito dalla
        // pagina Impostazioni (GeneralSettings); se non impostato non viene
        // iniettato nulla e resta lo sfondo di default. CSS scoped alla login.
        ->renderHook(
            PanelsRenderHook::HEAD_END,
            function (): string|HtmlString {
                $settings = app(GeneralSettings::class);

                if (blank($settings->login_background_path)) {
                    return '';
                }

                $url = Storage::disk('public')->url($settings->login_background_path);
                $overlay = self::overlayRgba($settings->login_overlay_color, $settings->login_overlay_opacity);

                return new HtmlString(
                    '<style>
                        .fi-simple-layout {
                            background-image: linear-gradient(' . $overlay . ', ' . $overlay . '), url("' . e($url) . '");
                            background-size: cover;
                            background-position: center;
                            background-repeat: no-repeat;
                        }
                    </style>',
                );
            },
            scopes: Login::class,
        );

    $primaryColor = config('digital-hub.primary_color');
    if (is_string($primaryColor) && $primaryColor !== '') {
        /** @var array<int, string> $color */
        $color = \Filament\Support\Colors\Color::{$primaryColor};
        $panel
        ->colors([
            'primary' => $color,
        ]);
    }

}

public function boot(Panel $panel): void
{
    Notifications::alignment(Alignment::Center);

    Table::configureUsing(function (Table $table): Table {
        return $table->defaultPaginationPageOption(50);
    });

    DigitalHubTableMacro::register();


}

/**
 * Costruisce una stringa CSS `rgba(...)` per l'overlay della login a partire
 * dal colore esadecimale (#rgb o #rrggbb) e dall'opacità (0..1) salvati nelle
 * impostazioni. Input non validi degradano a nero/opacità clampata.
 */
private static function overlayRgba(string $hex, float $opacity): string
{
    $hex = ltrim($hex, '#');

    if (strlen($hex) === 3) {
        $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
    }

    if (! ctype_xdigit($hex) || strlen($hex) !== 6) {
        $hex = '000000';
    }

    $r = (int) hexdec(substr($hex, 0, 2));
    $g = (int) hexdec(substr($hex, 2, 2));
    $b = (int) hexdec(substr($hex, 4, 2));
    $alpha = max(0.0, min(1.0, $opacity));

